<?php require_once '../includes/auth.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$q=$pdo->prepare('SELECT * FROM users WHERE email=?');$q->execute([$_POST['email']??'']);$u=$q->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){if($u['account_status']==='suspended'){$error='This account is suspended.';}else{session_regenerate_id(true);$_SESSION['user_id']=$u['id'];go('/seller/dashboard.php');}}else $error='Invalid credentials.';}$title='Login';require '../includes/header.php';?><h1>Login</h1><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="card card-body col-lg-6"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="form-control mb-2" type="email" name="email" placeholder="Email" required><input class="form-control mb-2" type="password" name="password" placeholder="Password" required><button class="btn btn-success">Login</button></form><?php require '../includes/footer.php';?>